// ---------------------------------------------------------------------------
// Pure helpers (no Win32 state). Covered by tests/engine_tests.cpp.
// ---------------------------------------------------------------------------
namespace cat {

constexpr int kSpriteSize = 32;
constexpr int kMaxScale = 4;
constexpr double kWalkSpeedPerScale = 30.0;  // physical px per second at 1x

struct AnimInfo {
    int firstFrame;
    int frameCount;
    int frameMs;
    bool loop;
};

// Top of the cat's head in a frame, in sprite pixels (facing right).
struct Anchor {
    int8_t x;
    int8_t y;
    bool upright;  // false when the head is upside down (belly up)
};

inline uint32_t PremultiplyArgb(uint32_t argb) {
    uint32_t a = argb >> 24;
    uint32_t r = ((argb >> 16) & 0xFF) * a / 255;
    uint32_t g = ((argb >> 8) & 0xFF) * a / 255;
    uint32_t b = (argb & 0xFF) * a / 255;
    return (a << 24) | (r << 16) | (g << 8) | b;
}

// Decodes one run-length encoded frame into premultiplied BGRA pixels (the
// layout a 32bpp DIB expects). Each byte is one run: high nibble = length - 1,
// low nibble = palette index. Returns false unless the runs fill exactly
// pixelCount pixels with valid palette indices.
inline bool DecodeRleFrame(const uint8_t* data, size_t size,
                           const uint32_t* palette, size_t paletteSize,
                           uint32_t* out, int pixelCount) {
    if (size % 2 != 0) {
        return false;
    }
    int filled = 0;
    for (size_t i = 0; i < size; i += 2) {
        int run = (int)data[i] + 1;
        size_t index = data[i + 1];
        if (index >= paletteSize || filled + run > pixelCount) {
            return false;
        }
        uint32_t pixel = PremultiplyArgb(palette[index]);
        for (int j = 0; j < run; j++) {
            out[filled++] = pixel;
        }
    }
    return filled == pixelCount;
}

// Frame within an animation after elapsedMs. Animations that don't loop hold
// their last frame.
inline int FrameInAnim(const AnimInfo& anim, uint64_t elapsedMs) {
    int step = (int)(elapsedMs / (uint64_t)anim.frameMs);
    if (anim.loop) {
        return step % anim.frameCount;
    }
    return step < anim.frameCount ? step : anim.frameCount - 1;
}

inline bool AnimDone(const AnimInfo& anim, uint64_t elapsedMs) {
    return !anim.loop &&
           elapsedMs >= (uint64_t)anim.frameMs * (uint64_t)anim.frameCount;
}

// sizeSetting 1..kMaxScale is a fixed multiplier; anything else means auto,
// which rounds the display scale to the nearest whole multiplier.
inline int ComputeScale(UINT dpi, int sizeSetting) {
    if (sizeSetting >= 1 && sizeSetting <= kMaxScale) {
        return sizeSetting;
    }
    int scale = (int)((dpi + 48) / 96);
    if (scale < 1) {
        return 1;
    }
    return scale > kMaxScale ? kMaxScale : scale;
}

// The window canvas: the cat in the bottom kSpriteSize rows, with headroom
// above it for effects such as hearts.
constexpr int kCanvasWidth = kSpriteSize;
constexpr int kEffectHeadroom = 16;
constexpr int kCanvasHeight = kSpriteSize + kEffectHeadroom;

// Premultiplied "source over destination".
inline uint32_t BlendOver(uint32_t src, uint32_t dst) {
    uint32_t inverse = 255 - (src >> 24);
    uint32_t out = 0;
    for (int shift = 0; shift < 32; shift += 8) {
        uint32_t s = (src >> shift) & 0xFF;
        uint32_t d = (dst >> shift) & 0xFF;
        out |= (s + d * inverse / 255) << shift;
    }
    return out;
}

// Hats are drawn with the brim's centre at this point of their cell.
constexpr int kHatPivotX = 16;
constexpr int kHatPivotY = 11;

// Builds the 1x canvas: the cat (mirrored when facing left) at the bottom,
// an optional hat placed in sprite coordinates at (hatX, hatY) that turns
// with the cat, and an optional effect sprite drawn over everything at
// canvas coordinates (effectX, effectY). Everything is clipped.
inline void ComposeCanvas(const uint32_t* catFrame, bool mirror,
                          const uint32_t* hatFrame, int hatX, int hatY,
                          const uint32_t* effectFrame, int effectX,
                          int effectY, uint32_t* canvas) {
    for (int i = 0; i < kCanvasWidth * kCanvasHeight; i++) {
        canvas[i] = 0;
    }
    for (int y = 0; y < kSpriteSize; y++) {
        for (int x = 0; x < kSpriteSize; x++) {
            int sx = mirror ? kSpriteSize - 1 - x : x;
            canvas[(y + kEffectHeadroom) * kCanvasWidth + x] =
                catFrame[y * kSpriteSize + sx];
        }
    }
    for (int y = 0; hatFrame && y < kSpriteSize; y++) {
        for (int x = 0; x < kSpriteSize; x++) {
            uint32_t px = hatFrame[y * kSpriteSize + x];
            int sx = hatX + x;
            int cx = mirror ? kSpriteSize - 1 - sx : sx;
            int cy = hatY + y + kEffectHeadroom;
            if (!(px >> 24) || cx < 0 || cy < 0 || cx >= kCanvasWidth ||
                cy >= kCanvasHeight) {
                continue;
            }
            uint32_t& dst = canvas[cy * kCanvasWidth + cx];
            dst = BlendOver(px, dst);
        }
    }
    if (!effectFrame) {
        return;
    }
    for (int y = 0; y < kSpriteSize; y++) {
        for (int x = 0; x < kSpriteSize; x++) {
            uint32_t px = effectFrame[y * kSpriteSize + x];
            int cx = effectX + x;
            int cy = effectY + y;
            if (!(px >> 24) || cx < 0 || cy < 0 || cx >= kCanvasWidth ||
                cy >= kCanvasHeight) {
                continue;
            }
            uint32_t& dst = canvas[cy * kCanvasWidth + cx];
            dst = BlendOver(px, dst);
        }
    }
}

// Days since 1970-01-01 for a calendar date (Howard Hinnant's algorithm).
constexpr int DaysFromCivil(int y, int m, int d) {
    y -= m <= 2;
    int era = (y >= 0 ? y : y - 399) / 400;
    int yoe = y - era * 400;
    int doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
    int doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    return era * 146097 + doe - 719468;
}

// The calendar month and day of a day number from DaysFromCivil.
inline void CivilMonthDay(int days, int* month, int* day) {
    days += 719468;
    int era = (days >= 0 ? days : days - 146096) / 146097;
    int doe = days - era * 146097;
    int yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    int doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    int mp = (5 * doy + 2) / 153;
    *day = doy - (153 * mp + 2) / 5 + 1;
    *month = mp + (mp < 10 ? 3 : -9);
}

// "YYYY-MM-DD" to a day number, or 0 if it isn't a valid date.
inline int ParseDate(const wchar_t* text) {
    int y = 0, m = 0, d = 0;
    if (!text || swscanf(text, L"%d-%d-%d", &y, &m, &d) != 3 || y < 1970 || m < 1 ||
        m > 12 || d < 1 || d > 31) {
        return 0;
    }
    return DaysFromCivil(y, m, d);
}

// Day 1 is the birthday itself.
inline int DayOfLife(int birthday, int today) {
    return today >= birthday ? today - birthday + 1 : 1;
}

enum class Hat { None, Witch, Santa, Party };

// Which hat to wear on a given date. birthdayMonth is 0 when the cat is less
// than a year old (no birthday yet).
inline Hat SeasonalHat(int month, int day, int birthdayMonth, int birthdayDay) {
    if (birthdayMonth != 0 && month == birthdayMonth && day == birthdayDay) {
        return Hat::Party;
    }
    if ((month == 12 && day == 31) || (month == 1 && day == 1)) {
        return Hat::Party;
    }
    if (month == 10 && day >= 15) {
        return Hat::Witch;
    }
    if (month == 12 && day <= 26) {
        return Hat::Santa;
    }
    return Hat::None;
}

// Mealtimes are 8:00-8:59 and 19:00-19:59. Returns an id for the meal at
// this hour (unique per day and meal), or -1 outside mealtimes.
constexpr int kBreakfastHour = 8;
constexpr int kDinnerHour = 19;

inline int MealKey(int dayNumber, int hour) {
    if (hour == kBreakfastHour) {
        return dayNumber * 2;
    }
    if (hour == kDinnerHour) {
        return dayNumber * 2 + 1;
    }
    return -1;
}

// Tells music from silence (and from short notification sounds) using the
// audio output's peak level, and estimates the beat.
constexpr double kMusicThreshold = 0.04;
constexpr double kMusicStartSeconds = 4.0;
constexpr double kMusicStopSeconds = 2.5;
constexpr double kBeatRise = 1.4;  // a beat is a peak this far above average
constexpr double kBeatFloor = 0.08;
constexpr uint64_t kMinBeatMs = 280;
constexpr uint64_t kMaxBeatMs = 1500;

struct MusicDetector {
    double loudSeconds;
    double quietSeconds;
    bool playing;
    double average;  // slow-moving average of the peak level
    uint64_t lastBeatMs;
    double beatMs;  // 0 until a steady beat is found
};

inline MusicDetector UpdateMusic(MusicDetector m, double peak, double dtSeconds,
                                 uint64_t now) {
    if (peak > kMusicThreshold) {
        m.loudSeconds += dtSeconds;
        m.quietSeconds = 0;
    } else {
        m.quietSeconds += dtSeconds;
        m.loudSeconds = m.loudSeconds > dtSeconds ? m.loudSeconds - dtSeconds : 0;
    }
    if (!m.playing && m.loudSeconds >= kMusicStartSeconds) {
        m.playing = true;
    } else if (m.playing && m.quietSeconds >= kMusicStopSeconds) {
        m = MusicDetector{};
        return m;
    }
    bool beat = peak > kBeatFloor && peak > m.average * kBeatRise &&
                now - m.lastBeatMs >= kMinBeatMs;
    if (beat) {
        uint64_t interval = now - m.lastBeatMs;
        if (m.lastBeatMs != 0 && interval <= kMaxBeatMs) {
            m.beatMs = m.beatMs > 0 ? m.beatMs * 0.7 + interval * 0.3 : (double)interval;
        }
        m.lastBeatMs = now;
    }
    m.average = m.average * 0.95 + peak * 0.05;
    return m;
}

// The cat sits on the bottom edge of the taskbar, wherever it is docked.
inline POINT ComputeWindowOrigin(const RECT& taskbar, double catX,
                                 int catHeight) {
    POINT origin;
    origin.x = taskbar.left + (LONG)catX;
    origin.y = taskbar.bottom - catHeight;
    return origin;
}

enum class RoamZone { AvoidTray, Whole, Custom };

struct RoamRange {
    double minX;
    double maxX;
};

// Where the cat's left edge may go, relative to the taskbar's left edge.
// trayLeft is the system tray's left edge (same frame), or <= 0 if unknown,
// in which case fallbackTrayWidth is assumed.
inline RoamRange ComputeRoamRange(int taskbarWidth, int catWidth, RoamZone zone,
                                  int trayLeft, int fallbackTrayWidth,
                                  int leftMargin, int rightMargin) {
    double minX = 0;
    double right = taskbarWidth;
    if (zone == RoamZone::AvoidTray) {
        right = trayLeft > 0 && trayLeft < taskbarWidth
                    ? trayLeft
                    : taskbarWidth - fallbackTrayWidth;
    } else if (zone == RoamZone::Custom) {
        minX = leftMargin;
        right = taskbarWidth - rightMargin;
    }
    double maxX = right - catWidth;
    return {minX, maxX > minX ? maxX : minX};
}

inline bool IsHorizontalTaskbar(const RECT& taskbar) {
    return (taskbar.right - taskbar.left) > (taskbar.bottom - taskbar.top);
}

// Taskbar counts as hidden when less than half of it is on its monitor
// (auto-hide slides it off screen).
inline bool IsMostlyOffMonitor(const RECT& taskbar, const RECT& monitor) {
    RECT visible;
    if (!IntersectRect(&visible, &taskbar, &monitor)) {
        return true;
    }
    LONG fullArea =
        (taskbar.right - taskbar.left) * (taskbar.bottom - taskbar.top);
    LONG visibleArea =
        (visible.right - visible.left) * (visible.bottom - visible.top);
    return visibleArea * 2 < fullArea;
}

}  // namespace cat

